 30	// nextConfiguration generates a new Configuration from the current one and a
 31	// configuration change request. It's split from appendConfigurationEntry so
 32	// that it can be unit tested easily.
 33	func nextConfiguration(current Configuration, currentIndex uint64, change configurationChangeRequest) (Configuration, error) {
 34		if change.prevIndex > 0 && change.prevIndex != currentIndex {
 35			return Configuration{}, fmt.Errorf("configuration changed since %v (latest is %v)", change.prevIndex, currentIndex)
 36		}
 37	
 38		configuration := current.Clone()
 39		switch change.command {
 40		case AddVoter:
 41			newServer := Server{
 42				Suffrage: Voter,
 43				ID:       change.serverID,
 44				Address:  change.serverAddress,
 45			}
 46			found := false
 47			for i, server := range configuration.Servers {
 48				if server.ID == change.serverID {
 49					if server.Suffrage == Voter {
 50						configuration.Servers[i].Address = change.serverAddress
 51					} else {
 52						configuration.Servers[i] = newServer
 53					}
 54					found = true
 55					break
 56				}
 57			}
 58			if !found {
 59				configuration.Servers = append(configuration.Servers, newServer)
 60			}
 61		case AddNonvoter:
 62			newServer := Server{
 63				Suffrage: Nonvoter,
 64				ID:       change.serverID,
 65				Address:  change.serverAddress,
 66			}
 67			found := false
 68			for i, server := range configuration.Servers {
 69				if server.ID == change.serverID {
 70					if server.Suffrage != Nonvoter {
 71						configuration.Servers[i].Address = change.serverAddress
 72					} else {
 73						configuration.Servers[i] = newServer
 74					}
 75					found = true
 76					break
 77				}
 78			}
 79			if !found {
 80				configuration.Servers = append(configuration.Servers, newServer)
 81			}
 82		case DemoteVoter:
 83			for i, server := range configuration.Servers {
 84				if server.ID == change.serverID {
 85					configuration.Servers[i].Suffrage = Nonvoter
 86					break
 87				}
 88			}
 89		case RemoveServer:
 90			for i, server := range configuration.Servers {
 91				if server.ID == change.serverID {
 92					configuration.Servers = append(configuration.Servers[:i], configuration.Servers[i+1:]...)
 93					break
 94				}
 95			}
 96		case Promote:
 97			for i, server := range configuration.Servers {
 98				if server.ID == change.serverID && server.Suffrage == Staging {
 99					configuration.Servers[i].Suffrage = Voter
100					break
101				}
102			}
103		}
104	
105		// Make sure we didn't do something bad like remove the last voter
106		if err := checkConfiguration(configuration); err != nil {
107			return Configuration{}, err
108		}
109	
110		return configuration, nil
111	}
