113	// encodePeers is used to serialize a Configuration into the old peers format.
114	// This is here for backwards compatibility when operating with a mix of old
115	// servers and should be removed once we deprecate support for protocol version 1.
116	func encodePeers(configuration Configuration, trans Transport) []byte {
117		// Gather up all the voters, other suffrage types are not supported by
118		// this data format.
119		var encPeers [][]byte
120		for _, server := range configuration.Servers {
121			if server.Suffrage == Voter {
122				encPeers = append(encPeers, trans.EncodePeer(server.ID, server.Address))
123			}
124		}
125	
126		// Encode the entire array.
127		buf, err := encodeMsgPack(encPeers)
128		if err != nil {
129			panic(fmt.Errorf("failed to encode peers: %v", err))
130		}
131	
132		return buf.Bytes()
133	}
